sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || oldValue === newValue) {
        return;
    } else if (newValue === '') {
		g_form.clearValue('requested_for_email', '');
        return;
    }

	// When Requested For field is changed
	// update the Requested For Email field with User's email if available.
	const AJAX = new GlideAjax('NeedItGlideAjax');
	AJAX.addParam('sysparm_name', 'getEmail');
	AJAX.addParam('sysparm_user_id', newValue);
	AJAX.getXMLAnswer((answer) => {
		// We could make sure the answer email is valid here
		// but it is probably okay to pass along whatever
		// value is in User email field (including undefined or null)

		g_form.setValue('requested_for_email', answer);
	});
}
